import {useEffect,useState} from 'react'
import {CarFront,Ticket,Wallet,Receipt,ChartNoAxesCombined,Settings,Droplets,Zap,Wrench,Users,LogOut,Building2,MapPin,Plus,RefreshCw} from 'lucide-react'
import {api,getToken,saveToken,clearToken,downloadFile} from './api'
const menu=[[ChartNoAxesCombined,'Tableau de bord','dashboard'],[Building2,'Entreprise','company'],[MapPin,'Stations','stations'],[Users,'Utilisateurs','users'],[Ticket,'Tickets de lavage','tickets'],[CarFront,'Prestations et tarifs','services'],[Wallet,'Recettes et caisse','cash'],[Receipt,'Dépenses','expenses'],[Wrench,'Stocks et fournisseurs','inventory'],[Droplets,'Suivi eau','water'],[Zap,'Suivi électricité','electricity'],[Wrench,'Immobilisations','assets'],[Users,'Personnel et paie','personnel'],[Settings,'Paramètres','settings']]
function Auth({onLogin}){const [mode,setMode]=useState('login');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
 async function submit(e){e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);const val=k=>String(f.get(k)||'').trim()
 try{const payload=mode==='login'?{email:val('email'),password:val('password')}:{bootstrap_secret:val('bootstrap_secret'),company_legal_name:val('company_legal_name'),company_display_name:val('company_display_name'),company_email:val('company_email')||null,company_phone:val('company_phone')||null,station_name:val('station_name'),station_code:val('station_code'),station_city:val('station_city')||null,owner_full_name:val('owner_full_name'),owner_email:val('owner_email'),password:val('password')}
 const result=await api(mode==='login'?'/api/v1/auth/login':'/api/v1/auth/register-owner',{method:'POST',body:payload,auth:false});saveToken(result.access_token);localStorage.setItem('alm_user_id',String(result.user_id));onLogin()
 }catch(err){setError(err.message)}finally{setBusy(false)}}
 return <div className="auth-wrap"><form className="auth-card" onSubmit={submit}><div className="auth-brand"><span><CarFront/></span><div><b>AUTO LAVAGE</b><small>MANAGER</small></div></div><h1>{mode==='login'?'Connexion':'Créer votre espace'}</h1><p className="muted">{mode==='login'?'Accédez à votre espace de gestion.':'Initialisez votre entreprise et votre première station.'}</p>
 {mode==='register'&&<><label>Code d’initialisation<input name="bootstrap_secret" required minLength="12" type="password"/></label><div className="form-grid"><label>Raison sociale<input name="company_legal_name" required minLength="2"/></label><label>Nom commercial<input name="company_display_name" required minLength="2"/></label><label>E-mail entreprise<input name="company_email" type="email"/></label><label>Téléphone<input name="company_phone"/></label><label>Première station<input name="station_name" required/></label><label>Code station<input name="station_code" required/></label><label>Ville<input name="station_city"/></label><label>Nom administrateur<input name="owner_full_name" required/></label></div><label>E-mail administrateur<input name="owner_email" type="email" required/></label></>}
 {mode==='login'&&<label>Adresse e-mail<input name="email" type="email" autoComplete="username" required/></label>}
 <label>Mot de passe<input name="password" type="password" minLength="12" autoComplete={mode==='login'?'current-password':'new-password'} required/></label>
 {error&&<div className="error">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Veuillez patienter…':mode==='login'?'Se connecter':'Créer mon espace'}</button><button type="button" className="text-button" onClick={()=>{setMode(mode==='login'?'register':'login');setError('')}}>{mode==='login'?'Première utilisation ? Initialiser une entreprise':'J’ai déjà un compte : me connecter'}</button><small className="security-note">Accès sécurisé · Données séparées par entreprise</small></form></div>}
function App(){const [token,setToken]=useState(!!getToken());const [page,setPage]=useState('dashboard');const [company,setCompany]=useState(null);const [stations,setStations]=useState([]);const [users,setUsers]=useState([]);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [showStation,setShowStation]=useState(false);const [showUser,setShowUser]=useState(false);const [services,setServices]=useState([]);const [tickets,setTickets]=useState([]);const [selectedTicket,setSelectedTicket]=useState(null);const [showService,setShowService]=useState(false);const [showTicket,setShowTicket]=useState(false);const [paymentTicket,setPaymentTicket]=useState(null);const [cash,setCash]=useState({sessions:[],summary:null});const [cashForm,setCashForm]=useState(false);const [expenses,setExpenses]=useState([]);const [expenseSummary,setExpenseSummary]=useState(null);const [expenseForm,setExpenseForm]=useState(false);const [paymentExpense,setPaymentExpense]=useState(null);const [products,setProducts]=useState([]);const [suppliers,setSuppliers]=useState([]);const [stockMovements,setStockMovements]=useState([]);const [inventorySummary,setInventorySummary]=useState(null);const [productForm,setProductForm]=useState(false);const [supplierForm,setSupplierForm]=useState(false);const [movementForm,setMovementForm]=useState(false);const [assets,setAssets]=useState([]);const [assetSummary,setAssetSummary]=useState(null);const [assetForm,setAssetForm]=useState(false);const [financial,setFinancial]=useState(null);const [financialPeriod,setFinancialPeriod]=useState('month');const [financialStation,setFinancialStation]=useState('');const [stationReport,setStationReport]=useState(null);const [employees,setEmployees]=useState([]);const [payrolls,setPayrolls]=useState([]);const [employeeForm,setEmployeeForm]=useState(false);const [payrollForm,setPayrollForm]=useState(false);const [selectedPayroll,setSelectedPayroll]=useState(null);const [payrollPaymentLine,setPayrollPaymentLine]=useState(null);const [payrollStationFilter,setPayrollStationFilter]=useState('');const [attendance,setAttendance]=useState([]);const [attendanceSummary,setAttendanceSummary]=useState(null);const [attendanceForm,setAttendanceForm]=useState(false);const [advances,setAdvances]=useState([]);const [advanceSummary,setAdvanceSummary]=useState(null);const [advanceForm,setAdvanceForm]=useState(false);const [repaymentAdvance,setRepaymentAdvance]=useState(null)
 async function load(){if(!getToken())return;setBusy(true);setError('');try{const c=await api('/api/v1/companies/me');setCompany(c);const s=await api('/api/v1/stations');setStations(s);if(c)setUsers(await api('/api/v1/users').catch(()=>[]))}catch(e){setError(e.message);if(e.message.includes('Authentification')||e.message.includes('Jeton')){clearToken();localStorage.removeItem('alm_user_id');setToken(false)}}finally{setBusy(false)}}
 useEffect(()=>{if(token)load()},[token]);useEffect(()=>{if(token&&['services','tickets','cash','expenses','assets','personnel','inventory'].includes(page))loadOperations()},[token,page]);useEffect(()=>{if(token&&page==='dashboard')loadFinancial()},[token,page,financialPeriod,financialStation]);useEffect(()=>{if(token&&page==='dashboard')loadStationReport()},[token,page,financialPeriod]);
 async function loadFinancial(){try{const q=new URLSearchParams({period:financialPeriod});if(financialStation)q.set('station_id',financialStation);setFinancial(await api('/api/v1/reports/financial?'+q.toString()))}catch(e){setError(e.message)}}
 async function loadStationReport(){try{const q=new URLSearchParams({period:financialPeriod});setStationReport(await api('/api/v1/reports/stations?'+q.toString()))}catch(e){setError(e.message)}}
 async function exportFinancial(format){try{const q=new URLSearchParams({format,period:financialPeriod});if(financialStation)q.set('station_id',financialStation);const extension=format==='xlsx'?'xlsx':'pdf';await downloadFile('/api/v1/reports/financial/export?'+q.toString(),'rapport_financier_'+new Date().toISOString().slice(0,10)+'.'+extension)}catch(e){setError(e.message)}}
 async function loadOperations(){try{if(page==='inventory'){const [p,s,m,sum]=await Promise.all([api('/api/v1/inventory/products'),api('/api/v1/suppliers'),api('/api/v1/inventory/movements'),api('/api/v1/inventory/summary')]);setProducts(p);setSuppliers(s);setStockMovements(m);setInventorySummary(sum)}if(page==='services')setServices(await api('/api/v1/services'));if(page==='tickets')setTickets(await api('/api/v1/tickets'));if(page==='cash'){const [summary,sessions]=await Promise.all([api('/api/v1/cash/summary'),api('/api/v1/cash/sessions')]);setCash({summary,sessions})}if(page==='expenses'){const [items,summary]=await Promise.all([api('/api/v1/expenses'),api('/api/v1/expenses/summary')]);setExpenses(items);setExpenseSummary(summary)}if(page==='assets'){const [items,summary]=await Promise.all([api('/api/v1/assets'),api('/api/v1/assets/summary')]);setAssets(items);setAssetSummary(summary)}if(page==='personnel'){const [staff,pay,att,summary,adv,advsum]=await Promise.all([api('/api/v1/employees?include_inactive=true'),api('/api/v1/payroll'),api('/api/v1/attendance'),api('/api/v1/attendance/summary'),api('/api/v1/advances'),api('/api/v1/advances/summary')]);setEmployees(staff);setPayrolls(pay);setAttendance(att);setAttendanceSummary(summary);setAdvances(adv);setAdvanceSummary(advsum)}}catch(e){setError(e.message)}}
 async function cashAction(e){e.preventDefault();const f=new FormData(e.currentTarget);try{if(f.get('action')==='open')await api('/api/v1/cash/sessions',{method:'POST',body:{station_id:Number(f.get('station_id')),opening_amount:Number(f.get('amount'))}});else if(f.get('action')==='close')await api('/api/v1/cash/sessions/'+f.get('session_id')+'/close',{method:'POST',body:{closing_amount:Number(f.get('amount'))}});else await api('/api/v1/cash/sessions/'+f.get('session_id')+'/movements',{method:'POST',body:{direction:f.get('direction'),amount:Number(f.get('amount')),reason:f.get('reason')}});setCashForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function createSupplier(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/suppliers',{method:'POST',body:{name:f.get('name'),phone:f.get('phone')||null,email:f.get('email')||null,address:f.get('address')||null}});setSupplierForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function createProduct(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/inventory/products',{method:'POST',body:{sku:f.get('sku'),name:f.get('name'),category:f.get('category'),unit:f.get('unit'),minimum_stock:Number(f.get('minimum_stock')||0)}});setProductForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function createStockMovement(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/inventory/movements',{method:'POST',body:{station_id:Number(f.get('station_id')),product_id:Number(f.get('product_id')),movement_type:f.get('movement_type'),quantity:Number(f.get('quantity')),supplier_id:f.get('supplier_id')?Number(f.get('supplier_id')):null,unit_cost:Number(f.get('unit_cost')||0),reference:f.get('reference')||null,note:f.get('note')||null}});setMovementForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function setSupplierPrice(productId,supplierId){const raw=window.prompt("Nouveau prix d'achat unitaire (FCFA)");if(raw===null)return;const price=Number(raw);if(!Number.isSafeInteger(price)||price<0){setError("Saisissez un prix entier positif ou nul.");return}try{await api('/api/v1/inventory/products/'+productId+'/suppliers/'+supplierId+'/price',{method:'PUT',body:{purchase_price:price}});loadOperations()}catch(e){setError(e.message)}}
 async function createExpense(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/expenses',{method:'POST',body:{station_id:Number(f.get('station_id')),category:f.get('category'),label:f.get('label'),vendor:f.get('vendor')||null,description:f.get('description')||null,expense_date:f.get('expense_date'),amount:Number(f.get('amount')),receipt_name:f.get('receipt_name')||null,receipt_url:f.get('receipt_url')||null}});setExpenseForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function payExpense(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/expenses/'+paymentExpense+'/payments',{method:'POST',body:{amount:Number(f.get('amount')),method:f.get('method'),reference:f.get('reference')||null}});setPaymentExpense(null);loadOperations()}catch(e){setError(e.message)}}
 async function exportAssets(format){try{const q=new URLSearchParams({format,as_of:new Date().toISOString().slice(0,10)});await downloadFile('/api/v1/assets/export?'+q.toString(),'registre_immobilisations_'+new Date().toISOString().slice(0,10)+'.'+format)}catch(e){setError(e.message)}}
 async function createAsset(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/assets',{method:'POST',body:{station_id:Number(f.get('station_id')),asset_code:f.get('asset_code'),name:f.get('name'),category:f.get('category'),supplier:f.get('supplier')||null,description:f.get('description')||null,acquisition_date:f.get('acquisition_date'),in_service_date:f.get('in_service_date'),acquisition_cost:Number(f.get('acquisition_cost')),residual_value:Number(f.get('residual_value')||0),useful_life_months:Number(f.get('useful_life_months')),depreciation_method:'straight_line'}});setAssetForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function createService(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/services',{method:'POST',body:{code:f.get('code'),name:f.get('name'),category:f.get('category'),price:Number(f.get('price')),duration_minutes:f.get('duration_minutes')?Number(f.get('duration_minutes')):null,station_id:f.get('station_id')?Number(f.get('station_id')):null,description:f.get('description')||null}});setShowService(false);loadOperations()}catch(e){setError(e.message)}}
 async function createTicket(e){e.preventDefault();const f=new FormData(e.currentTarget);const ids=[...e.currentTarget.querySelectorAll('[name="service_id"]')].map(x=>Number(x.value)).filter(Boolean);const lines=ids.map(id=>({service_id:id,quantity:1}));try{await api('/api/v1/tickets',{method:'POST',body:{station_id:Number(f.get('station_id')),customer_name:f.get('customer_name')||null,customer_phone:f.get('customer_phone')||null,vehicle_type:f.get('vehicle_type'),vehicle_registration:f.get('vehicle_registration')||null,lines}});setShowTicket(false);loadOperations()}catch(e){setError(e.message)}}
 async function openTicket(id){try{setSelectedTicket(await api('/api/v1/tickets/'+id))}catch(e){setError(e.message)}}
 async function payTicket(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/tickets/'+paymentTicket+'/payments',{method:'POST',body:{amount:Number(f.get('amount')),method:f.get('method'),reference:f.get('reference')||null}});setPaymentTicket(null);await openTicket(paymentTicket);loadOperations()}catch(e){setError(e.message)}}
 
 async function createAdvance(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/advances',{method:'POST',body:{employee_id:Number(f.get('employee_id')),amount:Number(f.get('amount')),reason:f.get('reason')}});setAdvanceForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function decideAdvance(id,decision){const note=window.prompt(decision==='approve'?'Commentaire de validation (facultatif)':'Motif du rejet (facultatif)')||null;try{await api('/api/v1/advances/'+id+'/'+decision,{method:'POST',body:{note}});loadOperations()}catch(e){setError(e.message)}}
 async function repayAdvance(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/advances/'+repaymentAdvance+'/repayments',{method:'POST',body:{amount:Number(f.get('amount')),reference:f.get('reference')||null,note:f.get('note')||null}});setRepaymentAdvance(null);loadOperations()}catch(e){setError(e.message)}}
 async function createAttendance(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/attendance',{method:'POST',body:{employee_id:Number(f.get('employee_id')),work_date:f.get('work_date'),status:f.get('status'),regular_hours:f.get('status')==='present'?Number(f.get('regular_hours')||0):0,overtime_hours:f.get('status')==='present'?Number(f.get('overtime_hours')||0):0,late_minutes:f.get('status')==='present'?Number(f.get('late_minutes')||0):0,leave_type:f.get('status')==='leave'?(f.get('leave_type')||null):null,note:f.get('note')||null}});setAttendanceForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function createEmployee(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/employees',{method:'POST',body:{station_id:Number(f.get('station_id')),employee_number:f.get('employee_number').trim(),full_name:f.get('full_name').trim(),phone:f.get('phone')||null,email:f.get('email')||null,job_title:f.get('job_title'),contract_type:f.get('contract_type'),hire_date:f.get('hire_date'),end_date:f.get('end_date')||null,salary_basis:f.get('salary_basis'),base_salary:Number(f.get('base_salary'))}});setEmployeeForm(false);loadOperations()}catch(e){setError(e.message)}}
 async function toggleEmployeeStatus(x){try{await api('/api/v1/employees/'+x.id+'/status',{method:'PATCH',body:{is_active:!x.is_active}});loadOperations()}catch(e){setError(e.message)}}
 async function createPayroll(e){e.preventDefault();const f=new FormData(e.currentTarget);const rows=[...e.currentTarget.querySelectorAll('[data-employee-id]')];const lines=rows.map(row=>({employee_id:Number(row.dataset.employeeId),base_salary:Number(row.querySelector('[name="base_salary"]').value||0),bonuses:Number(row.querySelector('[name="bonuses"]').value||0),overtime_pay:Number(row.querySelector('[name="overtime_pay"]').value||0),deductions:Number(row.querySelector('[name="deductions"]').value||0),employee_contributions:Number(row.querySelector('[name="employee_contributions"]').value||0),employer_contributions:Number(row.querySelector('[name="employer_contributions"]').value||0),advance_deduction:Number(row.querySelector('[name="advance_deduction"]').value||0)}));try{const p=await api('/api/v1/payroll',{method:'POST',body:{station_id:Number(f.get('station_id')),period_type:f.get('period_type'),start_date:f.get('start_date'),end_date:f.get('end_date'),lines}});setPayrollForm(false);setSelectedPayroll(p);loadOperations()}catch(e){setError(e.message)}}
 async function validatePayroll(id){if(!window.confirm('Confirmer la validation ? Les montants seront figés.'))return;try{const p=await api('/api/v1/payroll/'+id+'/validate',{method:'POST'});setSelectedPayroll(p);loadOperations()}catch(e){setError(e.message)}}
 async function exportPayroll(id,format){try{await downloadFile('/api/v1/payroll/'+id+'/export?format='+format,'etat_paie_'+id+'.'+format)}catch(e){setError(e.message)}}
 async function exportBulletin(id){try{await downloadFile('/api/v1/payroll/lines/'+id+'/bulletin','bulletin_salarie_'+id+'.pdf')}catch(e){setError(e.message)}}
 async function payPayroll(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/payroll/lines/'+payrollPaymentLine+'/payments',{method:'POST',body:{amount:Number(f.get('amount')),method:f.get('method'),reference:f.get('reference')||null}});setPayrollPaymentLine(null);const rows=await api('/api/v1/payroll');setPayrolls(rows);const current=rows.find(x=>x.id===selectedPayroll?.id);if(current)setSelectedPayroll(current)}catch(e){setError(e.message)}}
 async function addStation(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/stations',{method:'POST',body:{name:f.get('name'),code:f.get('code'),city:f.get('city')||null,address:f.get('address')||null}});setShowStation(false);load()}catch(e){setError(e.message)}}
 async function addUser(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/users',{method:'POST',body:{full_name:f.get('full_name'),email:f.get('email'),password:f.get('password'),role:f.get('role'),station_id:f.get('station_id')?Number(f.get('station_id')):null}});setShowUser(false);load()}catch(e){setError(e.message)}}
 async function toggleUser(u){try{await api('/api/v1/users/'+u.id+'/status',{method:'PATCH',body:{is_active:!u.is_active}});load()}catch(e){setError(e.message)}}
 if(!token)return <Auth onLogin={()=>setToken(true)}/>
 const pageTitle=menu.find(x=>x[2]===page)?.[1]||'Tableau de bord'
 return <div className="shell"><aside className="sidebar"><div className="brand"><span className="brand-icon"><CarFront/></span><div><b>AUTO LAVAGE</b><small>MANAGER</small></div></div><div className="workspace"><small>ENTREPRISE</small><b>{company?.display_name||'Chargement…'}</b></div><nav>{menu.map(([Icon,label,id])=><button className={page===id?'active':''} onClick={()=>setPage(id)} key={id}><Icon size={18}/><span>{label}</span></button>)}</nav><button className="logout" onClick={()=>{clearToken();localStorage.removeItem('alm_user_id');setToken(false)}}><LogOut size={17}/> Déconnexion</button><div className="side-foot">Version 0.3.0</div></aside><main className="main"><header><div><small>ESPACE DE GESTION · XOF (FCFA)</small><h1>{pageTitle}</h1></div><div className="header-actions"><button className="icon-btn" onClick={load} title="Actualiser"><RefreshCw size={17}/></button><div className="user">{company?.display_name||'Mon entreprise'}</div></div></header>
 {error&&<div className="error page-error">{error}</div>}{busy&&<p className="muted">Actualisation…</p>}
 {page==='dashboard'&&<><section className="panel"><div className="panel-head"><div><h2>Synthèse financière</h2><p className="muted">Indicateurs consolidés de l’entreprise et de ses stations.</p></div><div className="quick-actions"><select value={financialPeriod} onChange={e=>setFinancialPeriod(e.target.value)}><option value="day">Aujourd’hui</option><option value="week">Cette semaine</option><option value="month">Ce mois</option><option value="year">Cette année</option></select><select value={financialStation} onChange={e=>setFinancialStation(e.target.value)}><option value="">Toutes les stations</option>{stations.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><button onClick={loadFinancial}>Actualiser</button><button onClick={()=>exportFinancial('pdf')}>Exporter PDF</button><button onClick={()=>exportFinancial('xlsx')}>Exporter Excel</button></div></div><div className="cards"><article><small>CHIFFRE D’AFFAIRES</small><strong>{Number(financial?.revenue||0).toLocaleString('fr-FR')} F</strong><span>{financial?.tickets_count||0} tickets créés</span></article><article><small>ENCAISSEMENTS</small><strong>{Number(financial?.collections||0).toLocaleString('fr-FR')} F</strong><span>Paiements reçus sur la période</span></article><article><small>CRÉANCES CLIENTS</small><strong>{Number(financial?.receivables_outstanding||0).toLocaleString('fr-FR')} F</strong><span>Solde de tous les tickets</span></article><article><small>CHARGES ENGAGÉES</small><strong>{Number(financial?.expenses_committed||0).toLocaleString('fr-FR')} F</strong><span>{financial?.expenses_count||0} dépenses sur la période</span></article><article><small>DÉCAISSEMENTS</small><strong>{Number(financial?.expense_disbursements||0).toLocaleString('fr-FR')} F</strong><span>Règlements effectués</span></article><article><small>DETTES DE CHARGES</small><strong>{Number(financial?.expense_liabilities_for_period||0).toLocaleString('fr-FR')} F</strong><span>Reste dû sur les charges de la période</span></article><article><small>DOTATIONS AUX AMORTISSEMENTS</small><strong>{Number(financial?.depreciation_charge||0).toLocaleString('fr-FR')} F</strong><span>Charge calculée, sans décaissement</span></article><article><small>RÉSULTAT SIMPLIFIÉ</small><strong>{Number(financial?.simplified_management_result||0).toLocaleString('fr-FR')} F</strong><span>CA − charges engagées − amortissements</span></article></div></section><section className="panel"><h2>Flux financiers de la période</h2><div className="detail-grid"><div><small>FLUX NET ENCAISSEMENTS − DÉCAISSEMENTS</small><b>{Number(financial?.net_cash_flow||0).toLocaleString('fr-FR')} FCFA</b></div><div><small>PÉRIODE ANALYSÉE</small><b>{financial?.start_date||'—'} au {financial?.end_date||'—'}</b></div></div><p className="muted">Le flux net n’est pas le solde réel de caisse ou de banque. Le résultat présenté est un indicateur de gestion simplifié, non une comptabilité certifiée. Les créances sont calculées sur tous les tickets visibles ; les dettes affichées concernent les dépenses de la période.</p></section></>}
 <section className="panel"><div className="panel-head"><div><h2>Comparatif de rentabilité par station</h2><p className="muted">Comparaison des performances sur la même période. Les stations partagées non ventilées ne sont pas réparties arbitrairement.</p></div><button onClick={loadStationReport}>Actualiser</button></div><div className="table-wrap"><table><thead><tr><th>Station</th><th>CA</th><th>Encaissements</th><th>Charges</th><th>Amortissements</th><th>Résultat simplifié</th><th>Flux net</th><th>Immobilisations (VNC)</th></tr></thead><tbody>{(stationReport?.stations||[]).map(s=><tr key={s.station_id}><td><b>{s.station_name}</b><small> {s.station_code}</small></td><td>{Number(s.revenue).toLocaleString('fr-FR')} F</td><td>{Number(s.collections).toLocaleString('fr-FR')} F</td><td>{Number(s.expenses_committed).toLocaleString('fr-FR')} F</td><td>{Number(s.depreciation_charge).toLocaleString('fr-FR')} F</td><td><b>{Number(s.simplified_management_result).toLocaleString('fr-FR')} F</b></td><td>{Number(s.net_cash_flow).toLocaleString('fr-FR')} F</td><td>{Number(s.asset_net_book_value).toLocaleString('fr-FR')} F</td></tr>)}{stationReport&&stationReport.stations.length===0&&<tr><td colSpan="8">Aucune station active à comparer.</td></tr>}</tbody></table></div><p className="muted">Période : {stationReport?.start_date||'—'} au {stationReport?.end_date||'—'} · {stationReport?.stations_count||0} station(s). Le résultat et le flux net sont des indicateurs simplifiés de gestion.</p></section>
 
 {page==='personnel'&&<><section className="cards"><article><small>SALARIÉS ACTIFS</small><strong>{employees.filter(x=>x.is_active).length}</strong><span>Personnel enregistré</span></article><article><small>PAIES PRÉPARÉES</small><strong>{payrolls.length}</strong><span>Périodes enregistrées</span></article><article><small>NETS À PAYER</small><strong>{payrolls.reduce((n,p)=>n+Number(p.remaining_total||0),0).toLocaleString('fr-FR')} F</strong><span>Soldes de paie restant dus</span></article><article><small>CHARGES PATRONALES</small><strong>{payrolls.reduce((n,p)=>n+Number(p.employer_contributions_total||0),0).toLocaleString('fr-FR')} F</strong><span>Total des périodes visibles</span></article></section>
<section className="panel"><div className="panel-head"><div><h2>Avances sur salaire</h2><p className="muted">Demandes, validation et remboursements. Une avance n'est pas déduite automatiquement d'une paie : la retenue correspondante doit être saisie dans la ligne de paie après contrôle.</p></div><button className="primary" onClick={()=>setAdvanceForm(!advanceForm)}><Plus size={16}/> Nouvelle demande</button></div><div className="cards"><article><small>DEMANDES EN ATTENTE</small><strong>{advanceSummary?.requests_count||0}</strong></article><article><small>AVANCES APPROUVÉES</small><strong>{Number(advanceSummary?.approved_amount||0).toLocaleString('fr-FR')} F</strong></article><article><small>RESTE À REMBOURSER</small><strong>{Number(advanceSummary?.outstanding_amount||0).toLocaleString('fr-FR')} F</strong></article></div>{advanceForm&&<form className="inline-form" onSubmit={createAdvance}><label>Salarié<select name="employee_id" required>{employees.filter(x=>x.is_active).map(x=><option key={x.id} value={x.id}>{x.employee_number} — {x.full_name}</option>)}</select></label><label>Montant FCFA<input name="amount" type="number" min="1" required/></label><label>Motif<input name="reason" minLength="3" maxLength="500" required/></label><button className="primary">Soumettre la demande</button></form>}{repaymentAdvance&&<form className="inline-form" onSubmit={repayAdvance}><strong>Enregistrer un remboursement</strong><label>Montant FCFA<input name="amount" type="number" min="1" required/></label><label>Référence<input name="reference" maxLength="100"/></label><label>Observation<input name="note" maxLength="500"/></label><button className="primary">Enregistrer</button><button type="button" onClick={()=>setRepaymentAdvance(null)}>Annuler</button></form>}<div className="table-wrap"><table><thead><tr><th>Date</th><th>Matricule</th><th>Salarié</th><th>Montant</th><th>Remboursé</th><th>Solde</th><th>Motif</th><th>Statut</th><th>Actions</th></tr></thead><tbody>{advances.map(x=><tr key={x.id}><td>{String(x.requested_at||'').slice(0,10)}</td><td>{x.employee_number}</td><td>{x.employee_name}</td><td>{x.amount.toLocaleString('fr-FR')}</td><td>{x.repaid_amount.toLocaleString('fr-FR')}</td><td>{x.remaining_amount.toLocaleString('fr-FR')}</td><td>{x.reason}</td><td>{({pending:'En attente',approved:'Approuvée',partially_repaid:'Partiellement remboursée',repaid:'Remboursée',rejected:'Rejetée'})[x.status]}</td><td>{x.status==='pending'&&<><button className="small-btn" onClick={()=>decideAdvance(x.id,'approve')}>Valider</button><button className="small-btn" onClick={()=>decideAdvance(x.id,'reject')}>Rejeter</button></>}{['approved','partially_repaid'].includes(x.status)&&<button className="small-btn" onClick={()=>setRepaymentAdvance(x.id)}>Rembourser</button>}</td></tr>)}{!advances.length&&<tr><td colSpan="9">Aucune avance enregistrée.</td></tr>}</tbody></table></div></section>
 <section className="panel"><div className="panel-head"><div><h2>Pointage, absences et congés</h2><p className="muted">Enregistrement journalier des présences, retards, heures supplémentaires et absences. Les heures supplémentaires sont saisies, non valorisées automatiquement.</p></div><button className="primary" onClick={()=>setAttendanceForm(!attendanceForm)}><Plus size={16}/> Nouveau pointage</button></div><div className="cards"><article><small>PRÉSENCES</small><strong>{attendanceSummary?.present_count||0}</strong></article><article><small>ABSENCES</small><strong>{attendanceSummary?.absent_count||0}</strong></article><article><small>CONGÉS</small><strong>{attendanceSummary?.leave_count||0}</strong></article><article><small>HEURES SUPPLÉMENTAIRES</small><strong>{attendanceSummary?.overtime_hours||0} h</strong></article></div>{attendanceForm&&<form className="inline-form" onSubmit={createAttendance}><label>Salarié<select name="employee_id" required>{employees.filter(x=>x.is_active).map(x=><option key={x.id} value={x.id}>{x.employee_number} — {x.full_name}</option>)}</select></label><label>Date<input name="work_date" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/></label><label>Situation<select name="status"><option value="present">Présent</option><option value="absent">Absent</option><option value="leave">Congé</option><option value="permission">Permission</option><option value="rest">Repos</option></select></label><label>Heures normales<input name="regular_hours" type="number" min="0" max="24" defaultValue="8"/></label><label>Heures supplémentaires<input name="overtime_hours" type="number" min="0" max="24" defaultValue="0"/></label><label>Retard (minutes)<input name="late_minutes" type="number" min="0" defaultValue="0"/></label><label>Type de congé<select name="leave_type"><option value="">Sans objet</option><option value="annual">Annuel</option><option value="sick">Maladie</option><option value="exceptional">Exceptionnel</option><option value="unpaid">Sans solde</option><option value="other">Autre</option></select></label><label>Observation<input name="note" maxLength="500"/></label><button className="primary">Enregistrer le pointage</button></form>}<div className="table-wrap"><table><thead><tr><th>Date</th><th>Matricule</th><th>Salarié</th><th>Statut</th><th>Heures normales</th><th>Heures sup.</th><th>Retard</th><th>Type congé</th><th>Observation</th></tr></thead><tbody>{attendance.map(x=><tr key={x.id}><td>{x.work_date}</td><td>{x.employee_number}</td><td>{x.employee_name}</td><td>{({present:'Présent',absent:'Absent',leave:'Congé',permission:'Permission',rest:'Repos'})[x.status]}</td><td>{x.regular_hours} h</td><td>{x.overtime_hours} h</td><td>{x.late_minutes} min</td><td>{x.leave_type||'—'}</td><td>{x.note||'—'}</td></tr>)}{!attendance.length&&<tr><td colSpan="9">Aucun pointage enregistré.</td></tr>}</tbody></table></div></section>
 <section className="panel"><div className="panel-head"><div><h2>Registre du personnel</h2><p className="muted">Fiches salariés, contrats et affectations aux stations.</p></div><button className="primary" onClick={()=>setEmployeeForm(!employeeForm)}><Plus size={16}/> Nouveau salarié</button></div>
 {employeeForm&&<form className="inline-form" onSubmit={createEmployee}><label>Station<select name="station_id" required>{stations.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Matricule<input name="employee_number" required maxLength="40"/></label><label>Nom et prénoms<input name="full_name" required/></label><label>Téléphone<input name="phone"/></label><label>E-mail<input name="email" type="email"/></label><label>Poste occupé<input name="job_title" required/></label><label>Type de contrat<select name="contract_type"><option value="permanent">CDI / Permanent</option><option value="fixed_term">CDD</option><option value="temporary">Temporaire</option><option value="daily">Journalier</option><option value="apprentice">Apprenti</option><option value="other">Autre</option></select></label><label>Date d'embauche<input name="hire_date" type="date" required/></label><label>Fin de contrat<input name="end_date" type="date"/></label><label>Périodicité salaire<select name="salary_basis"><option value="monthly">Mensuelle</option><option value="weekly">Hebdomadaire</option></select></label><label>Salaire de base (FCFA)<input name="base_salary" type="number" min="0" required/></label><button className="primary">Enregistrer le salarié</button></form>}
 <div className="table-wrap"><table><thead><tr><th>Matricule</th><th>Nom</th><th>Station</th><th>Poste</th><th>Contrat</th><th>Périodicité</th><th>Salaire de base</th><th>Statut</th><th>Action</th></tr></thead><tbody>{employees.map(x=><tr key={x.id}><td>{x.employee_number}</td><td>{x.full_name}<small>{x.phone||''}</small></td><td>{stations.find(s=>s.id===x.station_id)?.name||'—'}</td><td>{x.job_title}</td><td>{({permanent:'Permanent',fixed_term:'CDD',temporary:'Temporaire',daily:'Journalier',apprentice:'Apprenti',other:'Autre'})[x.contract_type]||x.contract_type}</td><td>{x.salary_basis==='weekly'?'Hebdomadaire':'Mensuelle'}</td><td>{Number(x.base_salary).toLocaleString('fr-FR')} F</td><td><span className={x.is_active?'badge':'badge inactive'}>{x.is_active?'Actif':'Inactif'}</span></td><td><button className="small-btn" onClick={()=>toggleEmployeeStatus(x)}>{x.is_active?'Désactiver':'Réactiver'}</button></td></tr>)}{!employees.length&&<tr><td colSpan="9">Aucun salarié enregistré.</td></tr>}</tbody></table></div></section>
 <section className="panel"><div className="panel-head"><div><h2>Préparation et suivi des paies</h2><p className="muted">Saisissez les éléments variables. Les cotisations sont paramétrées manuellement à ce stade : aucun taux légal automatique n'est appliqué.</p></div><button className="primary" onClick={()=>setPayrollForm(!payrollForm)}><Plus size={16}/> Préparer une paie</button></div>
 {payrollForm&&<form onSubmit={createPayroll}><div className="inline-form"><label>Station<select name="station_id" required value={payrollStationFilter||String(stations[0]?.id||'')} onChange={e=>setPayrollStationFilter(e.target.value)}>{stations.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Type de période<select name="period_type"><option value="monthly">Mensuelle</option><option value="weekly">Hebdomadaire</option></select></label><label>Du<input name="start_date" type="date" required/></label><label>Au<input name="end_date" type="date" required/></label></div><div className="table-wrap"><table><thead><tr><th>Salarié</th><th>Salaire de base</th><th>Primes</th><th>Heures sup.</th><th>Retenues</th><th>Cot. salariales</th><th>Cot. patronales</th><th>Avances à déduire</th></tr></thead><tbody>{employees.filter(x=>x.is_active&&x.station_id===Number(payrollStationFilter||stations[0]?.id)).map(x=><tr data-employee-id={x.id} key={x.id}><td>{x.full_name}<small>{x.employee_number}</small></td><td><input aria-label="Salaire de base" name="base_salary" type="number" min="0" defaultValue={x.base_salary}/></td><td><input aria-label="Primes" name="bonuses" type="number" min="0" defaultValue="0"/></td><td><input aria-label="Heures supplémentaires" name="overtime_pay" type="number" min="0" defaultValue="0"/></td><td><input aria-label="Retenues" name="deductions" type="number" min="0" defaultValue="0"/></td><td><input aria-label="Cotisations salariales" name="employee_contributions" type="number" min="0" defaultValue="0"/></td><td><input aria-label="Cotisations patronales" name="employer_contributions" type="number" min="0" defaultValue="0"/></td><td><input aria-label="Avances" name="advance_deduction" type="number" min="0" defaultValue="0"/></td></tr>)}</tbody></table></div><div className="quick-actions"><button className="primary" disabled={!employees.some(x=>x.is_active&&x.station_id===Number(payrollStationFilter||stations[0]?.id))}>Enregistrer la paie en brouillon</button><button type="button" onClick={()=>setPayrollForm(false)}>Annuler</button></div></form>}
 <div className="table-wrap"><table><thead><tr><th>Période</th><th>Station</th><th>Type</th><th>Brut</th><th>Net à payer</th><th>Réglé</th><th>Reste dû</th><th>Statut</th><th></th></tr></thead><tbody>{payrolls.map(p=><tr key={p.id}><td>{p.start_date} au {p.end_date}</td><td>{stations.find(s=>s.id===p.station_id)?.name||'—'}</td><td>{p.period_type==='weekly'?'Hebdomadaire':'Mensuelle'}</td><td>{Number(p.gross_total).toLocaleString('fr-FR')} F</td><td>{Number(p.net_due_total).toLocaleString('fr-FR')} F</td><td>{Number(p.paid_total).toLocaleString('fr-FR')} F</td><td>{Number(p.remaining_total).toLocaleString('fr-FR')} F</td><td><span className="badge">{p.status==='draft'?'Brouillon':p.status==='validated'?'Validée':'Payée'}</span></td><td><button className="small-btn" onClick={()=>setSelectedPayroll(p)}>Détail</button></td></tr>)}{!payrolls.length&&<tr><td colSpan="9">Aucune paie préparée.</td></tr>}</tbody></table></div></section>
 {selectedPayroll&&<section className="panel"><div className="panel-head"><div><h2>Détail de la paie #{selectedPayroll.id}</h2><p className="muted">{selectedPayroll.start_date} au {selectedPayroll.end_date} · {selectedPayroll.status==='draft'?'Brouillon':selectedPayroll.status==='validated'?'Validée':'Payée'}</p></div><div className="quick-actions"><button onClick={()=>exportPayroll(selectedPayroll.id,'pdf')}>État PDF</button><button onClick={()=>exportPayroll(selectedPayroll.id,'xlsx')}>État Excel</button>{selectedPayroll.status==='draft'&&<button className="primary" onClick={()=>validatePayroll(selectedPayroll.id)}>Valider la paie</button>}<button onClick={()=>setSelectedPayroll(null)}>Fermer</button></div></div><div className="table-wrap"><table><thead><tr><th>Salarié</th><th>Brut</th><th>Retenues</th><th>Cot. salariales</th><th>Avance</th><th>Net dû</th><th>Payé</th><th>Reste</th><th>Action</th></tr></thead><tbody>{selectedPayroll.lines?.map(l=><tr key={l.id}><td>{l.employee_name}<small>{l.employee_number}</small></td><td>{Number(l.gross_salary).toLocaleString('fr-FR')} F</td><td>{Number(l.deductions).toLocaleString('fr-FR')} F</td><td>{Number(l.employee_contributions).toLocaleString('fr-FR')} F</td><td>{Number(l.advance_deduction).toLocaleString('fr-FR')} F</td><td><b>{Number(l.net_due).toLocaleString('fr-FR')} F</b></td><td>{Number(l.paid_amount).toLocaleString('fr-FR')} F</td><td>{Number(l.remaining_amount).toLocaleString('fr-FR')} F</td><td><button className="small-btn" onClick={()=>exportBulletin(l.id)}>Bulletin PDF</button>{selectedPayroll.status!=='draft'&&l.remaining_amount>0&&<button className="small-btn" onClick={()=>setPayrollPaymentLine(l.id)}>Régler</button>}</td></tr>)}</tbody></table></div>{payrollPaymentLine&&<form className="inline-form" onSubmit={payPayroll}><b>Règlement du salarié</b><label>Montant (FCFA)<input name="amount" type="number" min="1" max={selectedPayroll.lines?.find(l=>l.id===payrollPaymentLine)?.remaining_amount||1} required/></label><label>Moyen de paiement<select name="method"><option value="cash">Espèces</option><option value="wave">Wave</option><option value="orange_money">Orange Money</option><option value="mtn_money">MTN Money</option><option value="moov_money">Moov Money</option><option value="card">Carte</option><option value="bank_transfer">Virement bancaire</option><option value="other">Autre</option></select></label><label>Référence<input name="reference"/></label><button className="primary">Enregistrer le paiement</button><button type="button" onClick={()=>setPayrollPaymentLine(null)}>Annuler</button></form>}</section>}
 </>}
 {page==='company'&&<section className="panel"><h2>Informations de l’entreprise</h2><div className="detail-grid"><div><small>RAISON SOCIALE</small><b>{company?.legal_name||'—'}</b></div><div><small>NOM COMMERCIAL</small><b>{company?.display_name||'—'}</b></div><div><small>E-MAIL</small><b>{company?.email||'Non renseigné'}</b></div><div><small>TÉLÉPHONE</small><b>{company?.phone||'Non renseigné'}</b></div><div><small>DEVISE</small><b>{company?.currency||'XOF'}</b></div></div></section>}
 {page==='stations'&&<section className="panel"><div className="panel-head"><div><h2>Stations de lavage</h2><p className="muted">Les stations rattachées à votre entreprise.</p></div><button className="primary" onClick={()=>setShowStation(!showStation)}><Plus size={16}/> Ajouter une station</button></div>{showStation&&<form className="inline-form" onSubmit={addStation}><label>Nom<input name="name" required/></label><label>Code<input name="code" required/></label><label>Ville<input name="city"/></label><label>Adresse<input name="address"/></label><button className="primary">Enregistrer</button></form>}<div className="table-wrap"><table><thead><tr><th>Nom</th><th>Code</th><th>Ville</th><th>Statut</th></tr></thead><tbody>{stations.map(s=><tr key={s.id}><td>{s.name}</td><td>{s.code}</td><td>{s.city||'—'}</td><td><span className="badge">Active</span></td></tr>)}{!stations.length&&<tr><td colSpan="4">Aucune station enregistrée.</td></tr>}</tbody></table></div></section>}
 {page==='users'&&<section className="panel"><div className="panel-head"><div><h2>Comptes utilisateurs</h2><p className="muted">Création et activation des accès à votre espace.</p></div><button className="primary" onClick={()=>setShowUser(!showUser)}><Plus size={16}/> Ajouter un utilisateur</button></div>{showUser&&<form className="inline-form" onSubmit={addUser}><label>Nom complet<input name="full_name" required/></label><label>E-mail<input name="email" type="email" required/></label><label>Mot de passe (12 caractères min.)<input name="password" type="password" minLength="12" required/></label><label>Rôle<select name="role"><option value="operator">Opérateur</option><option value="cashier">Caissier</option><option value="station_manager">Responsable station</option><option value="company_admin">Administrateur entreprise</option></select></label><label>Station<select name="station_id"><option value="">Toutes / non affecté</option>{stations.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><button className="primary">Créer le compte</button></form>}<div className="table-wrap"><table><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Statut</th><th>Action</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td>{u.full_name}</td><td>{u.email}</td><td>{u.role}</td><td><span className={u.is_active?'badge':'badge inactive'}>{u.is_active?'Actif':'Désactivé'}</span></td><td><button className="small-btn" disabled={u.id===Number(localStorage.getItem('alm_user_id'))} onClick={()=>toggleUser(u)}>{u.is_active?'Désactiver':'Activer'}</button></td></tr>)}{!users.length&&<tr><td colSpan="5">Aucun utilisateur visible ou droits administrateur requis.</td></tr>}</tbody></table></div></section>}
 {page==='services'&&<section className="panel"><div className="panel-head"><div><h2>Catalogue des prestations</h2><p className="muted">Tarifs en FCFA. Une prestation peut être commune à l’entreprise ou propre à une station.</p></div><button className="primary" onClick={()=>setShowService(!showService)}><Plus size={16}/> Nouvelle prestation</button></div>{showService&&<form className="inline-form" onSubmit={createService}><label>Code<input name="code" required/></label><label>Nom<input name="name" required/></label><label>Catégorie<input name="category" defaultValue="lavage" required/></label><label>Prix (FCFA)<input name="price" type="number" min="0" required/></label><label>Durée (minutes)<input name="duration_minutes" type="number" min="1"/></label><label>Station<select name="station_id"><option value="">Toutes les stations</option>{stations.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Description<input name="description"/></label><button className="primary">Enregistrer</button></form>}<div className="table-wrap"><table><thead><tr><th>Code</th><th>Prestation</th><th>Catégorie</th><th>Station</th><th>Durée</th><th>Prix</th><th>Statut</th></tr></thead><tbody>{services.map(s=><tr key={s.id}><td>{s.code}</td><td>{s.name}</td><td>{s.category}</td><td>{stations.find(x=>x.id===s.station_id)?.name||'Toutes'}</td><td>{s.duration_minutes? s.duration_minutes+' min':'—'}</td><td>{Number(s.price).toLocaleString('fr-FR')} F</td><td><span className={s.is_active?'badge':'badge inactive'}>{s.is_active?'Active':'Inactive'}</span></td></tr>)}{!services.length&&<tr><td colSpan="7">Aucune prestation. Ajoutez votre premier tarif.</td></tr>}</tbody></table></div></section>}
 {page==='tickets'&&<section className="panel"><div className="panel-head"><div><h2>Tickets de lavage</h2><p className="muted">Création des tickets et suivi des paiements.</p></div><button className="primary" onClick={()=>setShowTicket(!showTicket)}><Plus size={16}/> Nouveau ticket</button></div>{showTicket&&<form className="inline-form" onSubmit={createTicket}><label>Station<select name="station_id" required>{stations.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Client<input name="customer_name"/></label><label>Téléphone<input name="customer_phone"/></label><label>Type de véhicule<input name="vehicle_type" placeholder="Berline, SUV, moto…" required/></label><label>Immatriculation<input name="vehicle_registration"/></label><label>Prestation 1<select name="service_id" required><option value="">Choisir…</option>{services.filter(s=>s.is_active).map(s=><option key={s.id} value={s.id}>{s.name} — {Number(s.price).toLocaleString("fr-FR")} F</option>)}</select></label><label>Prestation 2<select name="service_id" ><option value="">Aucune</option>{services.filter(s=>s.is_active).map(s=><option key={s.id} value={s.id}>{s.name} — {Number(s.price).toLocaleString("fr-FR")} F</option>)}</select></label><label>Prestation 3<select name="service_id" ><option value="">Aucune</option>{services.filter(s=>s.is_active).map(s=><option key={s.id} value={s.id}>{s.name} — {Number(s.price).toLocaleString("fr-FR")} F</option>)}</select></label><button className="primary">Créer le ticket</button></form>}<div className="table-wrap"><table><thead><tr><th>Numéro</th><th>Date</th><th>Client</th><th>Véhicule</th><th>Total</th><th>Payé</th><th>Solde</th><th>Statut</th><th></th></tr></thead><tbody>{tickets.map(t=><tr key={t.id}><td>{t.ticket_number}</td><td>{t.created_at?new Date(t.created_at).toLocaleString('fr-FR'):'—'}</td><td>{t.customer_name||'Client comptoir'}</td><td>{t.vehicle_type}</td><td>{Number(t.total).toLocaleString('fr-FR')} F</td><td>{Number(t.paid_amount).toLocaleString('fr-FR')} F</td><td>{Number(t.remaining_amount).toLocaleString('fr-FR')} F</td><td><span className="badge">{t.status}</span></td><td><button className="small-btn" onClick={()=>openTicket(t.id)}>Détail</button></td></tr>)}{!tickets.length&&<tr><td colSpan="9">Aucun ticket enregistré.</td></tr>}</tbody></table></div>{selectedTicket&&<div className="panel"><div className="panel-head"><div><h2>Ticket {selectedTicket.ticket_number}</h2><p className="muted">{selectedTicket.customer_name||'Client comptoir'} · {selectedTicket.vehicle_type} · {selectedTicket.vehicle_registration||'Sans immatriculation'}</p></div><div className="quick-actions"><button onClick={()=>window.print()}>Imprimer</button><button onClick={()=>setSelectedTicket(null)}>Fermer</button></div></div><div className="table-wrap"><table><thead><tr><th>Prestation</th><th>Qté</th><th>Prix unitaire</th><th>Total</th></tr></thead><tbody>{selectedTicket.lines?.map(l=><tr key={l.id}><td>{l.service_name}</td><td>{l.quantity}</td><td>{Number(l.unit_price).toLocaleString('fr-FR')} F</td><td>{Number(l.line_total).toLocaleString('fr-FR')} F</td></tr>)}</tbody></table></div><p><b>Total : {Number(selectedTicket.total).toLocaleString('fr-FR')} FCFA · Payé : {Number(selectedTicket.paid_amount).toLocaleString('fr-FR')} FCFA · Solde : {Number(selectedTicket.remaining_amount).toLocaleString('fr-FR')} FCFA</b></p>{selectedTicket.remaining_amount>0&&<button className="primary" onClick={()=>setPaymentTicket(selectedTicket.id)}>Enregistrer un encaissement</button>}{paymentTicket===selectedTicket.id&&<form className="inline-form" onSubmit={payTicket}><label>Montant (FCFA)<input name="amount" type="number" min="1" max={selectedTicket.remaining_amount} required/></label><label>Moyen de paiement<select name="method"><option value="cash">Espèces</option><option value="wave">Wave</option><option value="orange_money">Orange Money</option><option value="mtn_money">MTN Money</option><option value="moov_money">Moov Money</option><option value="card">Carte</option><option value="other">Autre</option></select></label><label>Référence<input name="reference"/></label><button className="primary">Valider le paiement</button></form>}</div>}</section>}
 {page==='assets'&&<><section className="cards"><article><small>IMMOBILISATIONS</small><strong>{assetSummary?.assets_count||0}</strong><span>Équipements enregistrés</span></article><article><small>COÛT D'ACQUISITION</small><strong>{Number(assetSummary?.acquisition_cost_total||0).toLocaleString('fr-FR')} F</strong><span>Valeur historique</span></article><article><small>AMORTISSEMENTS CUMULÉS</small><strong>{Number(assetSummary?.accumulated_depreciation_total||0).toLocaleString('fr-FR')} F</strong><span>À la date du jour</span></article><article><small>VALEUR NETTE COMPTABLE</small><strong>{Number(assetSummary?.net_book_value_total||0).toLocaleString('fr-FR')} F</strong><span>Valeur nette comptable</span></article></section><section className="panel"><div className="panel-head"><div><h2>Registre des immobilisations</h2><p className="muted">Amortissement linéaire mensuel indicatif. Les dotations ne constituent pas des sorties de trésorerie.</p></div><div className="quick-actions"><button onClick={()=>exportAssets('pdf')}>Exporter PDF</button><button onClick={()=>exportAssets('xlsx')}>Exporter Excel</button><button className="primary" onClick={()=>setAssetForm(!assetForm)}><Plus size={16}/> Nouvelle immobilisation</button></div></div>{assetForm&&<form className="inline-form" onSubmit={createAsset}><label>Station<select name="station_id" required>{stations.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Code immobilisation<input name="asset_code" required/></label><label>Désignation<input name="name" required/></label><label>Catégorie<input name="category" placeholder="Matériel de lavage" required/></label><label>Fournisseur<input name="supplier"/></label><label>Date d'acquisition<input name="acquisition_date" type="date" required/></label><label>Date de mise en service<input name="in_service_date" type="date" required/></label><label>Coût d'acquisition (FCFA)<input name="acquisition_cost" type="number" min="1" required/></label><label>Valeur résiduelle (FCFA)<input name="residual_value" type="number" min="0" defaultValue="0"/></label><label>Durée d'utilisation (mois)<input name="useful_life_months" type="number" min="1" max="1200" required/></label><label>Description<input name="description"/></label><button className="primary">Enregistrer l'immobilisation</button></form>}<div className="table-wrap"><table><thead><tr><th>Code</th><th>Immobilisation</th><th>Station</th><th>Acquisition</th><th>Coût</th><th>Durée</th><th>Dotation mensuelle</th><th>Amortissements cumulés</th><th>VNC</th></tr></thead><tbody>{assets.map(a=><tr key={a.id}><td>{a.asset_code}</td><td>{a.name} · {a.category}</td><td>{stations.find(s=>s.id===a.station_id)?.name||'—'}</td><td>{a.acquisition_date}</td><td>{Number(a.acquisition_cost).toLocaleString('fr-FR')} F</td><td>{a.useful_life_months} mois</td><td>{Number(a.fully_depreciated?0:a.monthly_depreciation).toLocaleString('fr-FR')} F</td><td>{Number(a.accumulated_depreciation).toLocaleString('fr-FR')} F</td><td>{Number(a.net_book_value).toLocaleString('fr-FR')} F</td></tr>)}{!assets.length&&<tr><td colSpan="9">Aucune immobilisation enregistrée.</td></tr>}</tbody></table></div><p className="muted">Méthode actuelle : linéaire. Les méthodes dégressives, proratas journaliers, sorties d'actifs et règles fiscales locales restent à valider avant usage comptable officiel.</p></section></>}
 {page==='inventory'&&<><section className="cards"><article><small>RÉFÉRENCES PRODUITS</small><strong>{inventorySummary?.products_count||0}</strong></article><article><small>UNITÉS EN STOCK</small><strong>{inventorySummary?.stock_units||0}</strong></article><article><small>ALERTES DE STOCK</small><strong>{inventorySummary?.low_stock_count||0}</strong></article><article><small>FOURNISSEURS</small><strong>{suppliers.length}</strong></article></section><section className="panel"><div className="panel-head"><div><h2>Catalogue et stock</h2><p className="muted">Les prix sont enregistrés par couple fournisseur-produit. Chaque entrée conserve son propre coût historique : modifier un tarif fournisseur ne modifie jamais les anciens achats.</p></div><div><button className="primary" onClick={()=>setProductForm(!productForm)}>Nouveau produit</button> <button onClick={()=>setSupplierForm(!supplierForm)}>Nouveau fournisseur</button> <button onClick={()=>setMovementForm(!movementForm)}>Mouvement de stock</button></div></div>{productForm&&<form className="inline-form" onSubmit={createProduct}><label>Code produit<input name="sku" required/></label><label>Désignation<input name="name" required/></label><label>Catégorie<input name="category" defaultValue="produits_lavage" required/></label><label>Unité<input name="unit" defaultValue="litre" required/></label><label>Seuil minimum<input name="minimum_stock" type="number" min="0" defaultValue="0"/></label><button className="primary">Créer le produit</button></form>}{supplierForm&&<form className="inline-form" onSubmit={createSupplier}><label>Nom fournisseur<input name="name" required/></label><label>Téléphone<input name="phone"/></label><label>E-mail<input name="email" type="email"/></label><label>Adresse<input name="address"/></label><button className="primary">Enregistrer le fournisseur</button></form>}{movementForm&&<form className="inline-form" onSubmit={createStockMovement}><label>Station<select name="station_id" required>{stations.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Produit<select name="product_id" required>{products.map(p=><option key={p.id} value={p.id}>{p.sku} — {p.name}</option>)}</select></label><label>Type<select name="movement_type"><option value="in">Entrée / achat</option><option value="out">Sortie / consommation</option><option value="adjustment">Ajustement inventaire (+)</option></select></label><label>Quantité<input name="quantity" type="number" min="1" required/></label><label>Fournisseur (entrée)<select name="supplier_id"><option value="">Aucun</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Coût unitaire FCFA<input name="unit_cost" type="number" min="0" defaultValue="0"/></label><label>Référence / facture<input name="reference"/></label><label>Observation<input name="note"/></label><button className="primary">Enregistrer le mouvement</button></form>}<div className="table-wrap"><table><thead><tr><th>Code</th><th>Produit</th><th>Catégorie</th><th>Stock total</th><th>Seuil</th><th>État</th><th>Tarifs fournisseurs</th></tr></thead><tbody>{products.map(p=><tr key={p.id}><td>{p.sku}</td><td>{p.name} ({p.unit})</td><td>{p.category}</td><td>{p.stock_total}</td><td>{p.minimum_stock}</td><td>{p.low_stock?'Stock bas':'Disponible'}</td><td>{p.supplier_prices.map(x=><div key={x.supplier_id}>{x.supplier_name}: {x.purchase_price.toLocaleString('fr-FR')} F <button className="small-btn" onClick={()=>setSupplierPrice(p.id,x.supplier_id)}>Modifier</button></div>)}{suppliers.filter(s=>!p.supplier_prices.some(x=>x.supplier_id===s.id)).map(s=><div key={s.id}>{s.name}: <button className="small-btn" onClick={()=>setSupplierPrice(p.id,s.id)}>Définir le prix</button></div>)}</td></tr>)}{!products.length&&<tr><td colSpan="7">Aucun produit enregistré.</td></tr>}</tbody></table></div></section><section className="panel"><h2>Historique des mouvements</h2><div className="table-wrap"><table><thead><tr><th>Date</th><th>Station</th><th>Produit</th><th>Type</th><th>Quantité</th><th>Coût unitaire</th><th>Fournisseur</th><th>Référence</th></tr></thead><tbody>{stockMovements.map(m=><tr key={m.id}><td>{String(m.moved_at||'').slice(0,10)}</td><td>{stations.find(s=>s.id===m.station_id)?.name||m.station_id}</td><td>{products.find(p=>p.id===m.product_id)?.name||m.product_id}</td><td>{m.movement_type}</td><td>{m.quantity}</td><td>{m.unit_cost.toLocaleString('fr-FR')} F</td><td>{suppliers.find(s=>s.id===m.supplier_id)?.name||'—'}</td><td>{m.reference||'—'}</td></tr>)}{!stockMovements.length&&<tr><td colSpan="8">Aucun mouvement de stock.</td></tr>}</tbody></table></div></section></>}
 
 {page==='expenses'&&<><section className="cards"><article><small>CHARGES ENGAGÉES</small><strong>{Number(expenseSummary?.committed_amount||0).toLocaleString('fr-FR')} F</strong><span>{expenseSummary?.expenses_count||0} dépenses</span></article><article><small>DÉCAISSEMENTS</small><strong>{Number(expenseSummary?.paid_amount||0).toLocaleString('fr-FR')} F</strong><span>Règlements effectués</span></article><article><small>RESTE À PAYER</small><strong>{Number(expenseSummary?.remaining_amount||0).toLocaleString('fr-FR')} F</strong><span>Dettes fournisseurs et charges</span></article><article><small>CATÉGORIES</small><strong>{Object.keys(expenseSummary?.by_category||{}).length}</strong><span>Types de charges utilisés</span></article></section><section className="panel"><div className="panel-head"><div><h2>Dépenses et charges</h2><p className="muted">Suivi des charges engagées et des décaissements réels. Les amortissements seront suivis séparément.</p></div><button className="primary" onClick={()=>setExpenseForm(!expenseForm)}><Plus size={16}/> Nouvelle dépense</button></div>{expenseForm&&<form className="inline-form" onSubmit={createExpense}><label>Station<select name="station_id" required>{stations.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Catégorie<select name="category"><option value="eau">Eau</option><option value="electricite">Électricité</option><option value="produits_lavage">Produits de lavage</option><option value="salaires">Salaires</option><option value="loyer">Loyer</option><option value="entretien">Entretien</option><option value="transport">Transport</option><option value="administration">Administration</option><option value="autres">Autres</option></select></label><label>Libellé<input name="label" required/></label><label>Fournisseur / bénéficiaire<input name="vendor"/></label><label>Date de dépense<input name="expense_date" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/></label><label>Montant engagé (FCFA)<input name="amount" type="number" min="1" required/></label><label>Description<input name="description"/></label><label>Nom du justificatif<input name="receipt_name"/></label><label>Lien du justificatif<input name="receipt_url" type="url"/></label><button className="primary">Enregistrer la dépense</button></form>}<div className="table-wrap"><table><thead><tr><th>Date</th><th>Station</th><th>Catégorie</th><th>Libellé</th><th>Montant</th><th>Payé</th><th>Reste</th><th>Statut</th><th></th></tr></thead><tbody>{expenses.map(x=><tr key={x.id}><td>{x.expense_date}</td><td>{stations.find(t=>t.id===x.station_id)?.name||'—'}</td><td>{x.category}</td><td>{x.label}{x.vendor?' · '+x.vendor:''}</td><td>{Number(x.amount).toLocaleString('fr-FR')} F</td><td>{Number(x.paid_amount).toLocaleString('fr-FR')} F</td><td>{Number(x.remaining_amount).toLocaleString('fr-FR')} F</td><td><span className={x.status==='paid'?'badge':x.status==='partial'?'badge':'badge inactive'}>{x.status==='paid'?'Payée':x.status==='partial'?'Partielle':'Impayée'}</span></td><td>{x.remaining_amount>0&&<button className="small-btn" onClick={()=>setPaymentExpense(x.id)}>Régler</button>}</td></tr>)}{!expenses.length&&<tr><td colSpan="9">Aucune dépense enregistrée.</td></tr>}</tbody></table></div>{paymentExpense&&<form className="inline-form" onSubmit={payExpense}><b>Règlement de la dépense #{paymentExpense}</b><label>Montant (FCFA)<input name="amount" type="number" min="1" max={expenses.find(x=>x.id===paymentExpense)?.remaining_amount||1} required/></label><label>Moyen de paiement<select name="method"><option value="cash">Espèces</option><option value="wave">Wave</option><option value="orange_money">Orange Money</option><option value="mtn_money">MTN Money</option><option value="moov_money">Moov Money</option><option value="card">Carte</option><option value="bank_transfer">Virement bancaire</option><option value="other">Autre</option></select></label><label>Référence<input name="reference"/></label><button className="primary">Valider le règlement</button><button type="button" onClick={()=>setPaymentExpense(null)}>Annuler</button></form>}</section></>}
 {page==='cash'&&<><section className="cards"><article><small>ENCAISSEMENTS CUMULÉS</small><strong>{Number(cash.summary?.total_collected||0).toLocaleString('fr-FR')} F</strong><span>{cash.summary?.payments_count||0} paiements</span></article><article><small>ESPÈCES</small><strong>{Number(cash.summary?.by_method?.cash||0).toLocaleString('fr-FR')} F</strong><span>Reçus en espèces</span></article><article><small>PAIEMENTS MOBILE</small><strong>{Number((cash.summary?.by_method?.wave||0)+(cash.summary?.by_method?.orange_money||0)+(cash.summary?.by_method?.mtn_money||0)+(cash.summary?.by_method?.moov_money||0)).toLocaleString('fr-FR')} F</strong><span>Mobile Money</span></article><article><small>CAISSES OUVERTES</small><strong>{cash.sessions.filter(x=>x.status==='open').length}</strong><span>Sessions en cours</span></article></section><section className="panel"><div className="panel-head"><div><h2>Sessions de caisse</h2><p className="muted">Ouverture, mouvements et rapprochement du solde physique.</p></div><button className="primary" onClick={()=>setCashForm(!cashForm)}>Nouvelle opération</button></div>{cashForm&&<form className="inline-form" onSubmit={cashAction}><label>Opération<select name="action"><option value="open">Ouvrir une caisse</option><option value="movement">Entrée ou sortie</option><option value="close">Clôturer une caisse</option></select></label><label>Station<select name="station_id">{stations.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Session ouverte<select name="session_id">{cash.sessions.filter(x=>x.status==='open').map(s=><option key={s.id} value={s.id}>#{s.id} — {stations.find(t=>t.id===s.station_id)?.name||'Station'}</option>)}</select></label><label>Sens du mouvement<select name="direction"><option value="in">Entrée</option><option value="out">Sortie</option></select></label><label>Montant (FCFA)<input name="amount" type="number" min="0" required/></label><label>Motif<input name="reason" defaultValue="Mouvement de caisse"/></label><button className="primary">Valider</button></form>}<div className="table-wrap"><table><thead><tr><th>Ouverture</th><th>Station</th><th>Fond initial</th><th>Espèces reçues</th><th>Solde théorique</th><th>Compté</th><th>Écart</th><th>État</th></tr></thead><tbody>{cash.sessions.map(s=><tr key={s.id}><td>{s.opened_at?new Date(s.opened_at).toLocaleString('fr-FR'):'—'}</td><td>{stations.find(t=>t.id===s.station_id)?.name||'—'}</td><td>{Number(s.opening_amount).toLocaleString('fr-FR')} F</td><td>{Number(s.cash_payments||0).toLocaleString('fr-FR')} F</td><td>{Number(s.expected_amount||0).toLocaleString('fr-FR')} F</td><td>{s.closing_amount==null?'—':Number(s.closing_amount).toLocaleString('fr-FR')+' F'}</td><td>{s.difference==null?'—':Number(s.difference).toLocaleString('fr-FR')+' F'}</td><td><span className={s.status==='open'?'badge':'badge inactive'}>{s.status==='open'?'Ouverte':'Clôturée'}</span></td></tr>)}{!cash.sessions.length&&<tr><td colSpan="8">Aucune session enregistrée.</td></tr>}</tbody></table></div></section></>}
 <footer>© AUTO LAVAGE MANAGER · Français · Devise XOF</footer></main></div>
}
export default App
